head.script:
scwin.autoComplete1_onfocus = function(info) {
    if (flag) {
        flag = false;
        WebSquare.wUnit.getDomById('input2').focus();
    }
};
scwin.autoComplete1_onviewchange = function(info) {
    flag = true;
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#input2').attr('class') == 'w2input w2input_focus';
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 autoComplete1_onfocus 를 확인한다.
    //1. In the Source tab, check autoComplete1_onfocus.
    //Test step 2. autoComplete1_onviewchange 를 확인한다.
    //2. Check autoComplete1_onviewchange.
    //Verify step 3. The focus is moved to the second inputBox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.f = [];
    for (var i = 0; i < 10; i++) {
        f.push(i + "A");
        f.push(i + "B");
    }
    dataList1.setData(f);
    window.flag = false;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 01-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
